INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das TMG nur für Websites?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Apps und andere Online-Dienste"}, {"text": "Ja", "correct": false, "because": "Umfassendere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das TMG?', 3, '[{"text": "Regulierung von Telemedien", "correct": true, "because": "Schutz und Rechtssicherheit"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Nicht primär"}, {"text": "Kostenreduktion", "correct": false, "because": "Rechtliche Vorgaben im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten legt das TMG Anbietern auf?', 5, '[{"text": "Impressumspflicht", "correct": true, "because": "Angaben zur Identität"}, {"text": "Datenschutzhinweise", "correct": true, "because": "Nutzerinformation"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das TMG fordert ein Impressum. b) Es gilt nur für kommerzielle Dienste.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch private Anbieter betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der TMG-Umsetzung?', 4, '[{"text": "Anbieterkennzeichnung", "correct": false, "because": "Pflicht im Impressum"}, {"text": "Datenschutzerklärung", "correct": false, "because": "Erforderlich für Nutzer"}, {"text": "Farbschema", "correct": true, "because": "Kein rechtlicher Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das TMG auch Datenschutz regelt?', 2, '[{"text": "Ja", "correct": true, "because": "Verweist auf Datenschutzgesetze"}, {"text": "Nein", "correct": false, "because": "Enthält Datenschutzvorgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Angabe ist im TMG-Impressum Pflicht?', 3, '[{"text": "Anbietername", "correct": true, "because": "Pflicht zur Identifikation"}, {"text": "Serverstandort", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt das TMG an Online-Dienste?', 5, '[{"text": "Kontaktdaten im Impressum", "correct": true, "because": "Erreichbarkeit sicherstellen"}, {"text": "Transparenz über Datenverarbeitung", "correct": true, "because": "Nutzerinformation"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das TMG schützt Nutzerdaten. b) Es gilt nur für deutsche Anbieter. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für Anbieter in Deutschland"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die TMG-Umsetzung?', 4, '[{"text": "Impressum", "correct": false, "because": "Gesetzliche Pflicht"}, {"text": "Datenschutzhinweise", "correct": false, "because": "Erforderlich"}, {"text": "Animationseffekte", "correct": true, "because": "Kein rechtlicher Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss das TMG-Impressum öffentlich sein?', 2, '[{"text": "Ja", "correct": true, "because": "Leicht zugänglich für Nutzer"}, {"text": "Nein", "correct": false, "because": "Öffentlichkeit vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste fallen unter das TMG?', 4, '[{"text": "Websites", "correct": true, "because": "Klassische Telemedien"}, {"text": "Mobile Apps", "correct": true, "because": "Auch Telemedien"}, {"text": "Hardware", "correct": false, "because": "Nicht betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das TMG nur für kommerzielle Anbieter gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch private Anbieter betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der TMG-Umsetzung?', 3, '[{"text": "Impressumspflicht", "correct": true, "because": "Gesetzliche Anforderung"}, {"text": "Schnelle Ladezeiten", "correct": false, "because": "Sekundär"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TMG fordert Datenschutzhinweise. b) Es gilt nur für große Anbieter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Anbieter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten legt das TMG fest?', 5, '[{"text": "Anbieterkennzeichnung", "correct": true, "because": "Impressum erforderlich"}, {"text": "Datennutzung transparent machen", "correct": true, "because": "Schutz der Nutzer"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Serverleistung", "correct": false, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der TMG-Umsetzung unwichtig?', 3, '[{"text": "Kontaktdaten", "correct": false, "because": "Pflicht im Impressum"}, {"text": "Datenschutzangaben", "correct": false, "because": "Erforderlich"}, {"text": "Schriftarten", "correct": true, "because": "Kein rechtlicher Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt das TMG auch für nicht-kommerzielle Anbieter?', 3, '[{"text": "Ja", "correct": true, "because": "Abhängig vom Angebot"}, {"text": "Nein", "correct": false, "because": "Nicht nur kommerziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das TMG Strafen vorsieht?', 2, '[{"text": "Ja", "correct": true, "because": "Verstöße können sanktioniert werden"}, {"text": "Nein", "correct": false, "because": "Sanktionen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für die TMG-Umsetzung?', 4, '[{"text": "Impressum", "correct": true, "because": "Gesetzliche Kennzeichnung"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Grafisches Design", "correct": false, "because": "Kein rechtlicher Fokus"}]');
